SELECT gen_random_uuid(), 'Slow Squat', 'Slow Squat is a strength exercise targeting Quads.', '​A tempo-based squat that uses controlled movement to increase muscle tension and improve lower-body stability. ​Lower: Descend slowly for 3 seconds. ​Pause: Hold at the bottom for 1 second. ​Stand: Return to the starting position at a normal pace. Form: Keep your chest up and weight in your heels.', 'GYM', 'Legs', 'Quads', 'BEGINNER', 5, NULL, '/seed-images/exercises/slow-squat.svg', NULL, ARRAY['/seed-images/exercises/slow-squat.svg'], NULL, 0, '["Hamstrings","Glutes","Abs"]', 'none (bodyweight exercise)', 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Quads', 60, NULL, NULL, 'strength', NULL
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE lower(name) = lower('Slow Squat') AND exercise_type = 'GYM');

