SELECT gen_random_uuid(), 'Wide Push-Up', 'Wide Push-Up is a strength exercise targeting Chest.', '​A push-up variation with a wider hand placement to increase the emphasis on the outer chest muscles and shoulders. ​Setup: Place hands wider than shoulder-width apart on the floor. Lower: Descend until your chest nearly touches the floor, keeping your core tight. ​Push: Drive through your palms to return to the start position. ​Form: Don''t let your lower back sag; keep a straight line from head to heels.', 'GYM', 'Chest', 'Chest', 'BEGINNER', 5, NULL, '/seed-images/exercises/wide-push-up.svg', NULL, ARRAY['/seed-images/exercises/wide-push-up.svg'], NULL, 0, '["Abs","Triceps"]', 'none (bodyweight exercise)', 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Chest', 60, NULL, NULL, 'strength', NULL
