SELECT gen_random_uuid(), 'Step Jack', 'Step Jack is an exercise targeting Legs.', 'The Step Jack is a low-impact plyometric-style move that provides cardiovascular benefits without the joint stress of jumping. It works the entire body, specifically targeting the legs, core, and shoulders. This move is ideal for beginners, individuals with joint sensitivities, or as a dynamic warm-up to gradually elevate the heart rate. Notes (Instructions): 1. ​Stand upright with your feet together and arms at your sides. 2. ​Step your right foot out to the side while simultaneously swinging both arms up above your head. 3. Bring your right foot back to the center and lower your arms. 4. ​Immediately repeat the movement, stepping out with your left foot. 5. ​Continue alternating sides at a steady, rhythmic pace.', 'CARDIO', 'Cardio', 'Legs', 'BEGINNER', 7, NULL, NULL, 0, '["Shoulders", "Glutes", "Obliquus externus abdominis", "Abs"]', 'none (bodyweight exercise)', 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, NULL, NULL, NULL, NULL, NULL, 30, 'MEDIUM', 'cardio', 8
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE lower(name) = lower('Step Jack') AND exercise_type = 'CARDIO');

