SELECT gen_random_uuid(), 'Kneeling kickbacks', 'Kneeling kickbacks is an exercise targeting Legs.', 'Starting position: Get down on all fours. Steps: 1. Push one foot back until fully extended, concentrating on the gluteus muscles. 2. Stay for one second, then return to the initial position. 3. Repeat, alternating feet.', 'GYM', 'Legs', 'Legs', 'BEGINNER', 5, NULL, 'https://wger.de/media/exercise-images/990/de20457c-914a-45c9-8cf9-0ad9739759a1.png', 0, '[]', 'none (bodyweight exercise)', 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Legs', 60, NULL, NULL, 'strength', NULL
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE lower(name) = lower('Kneeling kickbacks') AND exercise_type = 'GYM');

