SELECT gen_random_uuid(), 'Jump rope: basic jumps', 'Jump rope: basic jumps is an exercise targeting Cardio.', 'Starting position: Put your feet close together, bend the knees a bit, keep your head and body straight, keep elbows in, open your arms. Steps: 1. Spin only your wrists with enough force to make the rope spin. 2. Jump just high enough to pass the rope below your feet. 3. Repeat. Notes: This exercise requires a jump rope. Make sure the rope length is adjusted to your height. One way to check is to grab both handles with one hand and stand on the middle of the rope hanging on the ground with one foot. If the rope (excluding the handles) reaches just below your chest, its length is right. A shorter rope would be hazardous, as you might hit yourself, and a longer rope would make for bad form.', 'CARDIO', 'Cardio', 'Cardio', 'BEGINNER', 7, NULL, NULL, 0, '[]', 'none (bodyweight exercise)', 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, NULL, NULL, NULL, NULL, NULL, 30, 'MEDIUM', 'cardio', 8
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE lower(name) = lower('Jump rope: basic jumps') AND exercise_type = 'CARDIO');

