SELECT gen_random_uuid(), 'Mountain climbers', 'Mountain climbers is an exercise targeting Chest.', 'Starting position: Start in the upright push-up position, aka. the high plank position.Hands should be directly under your shoulders.Keep your head in line with your back, facing the floor.Feet should be about hip-width apart. Steps: 1. Move one knee toward the center of your body, towards your elbows, keeping the other leg extended. 2. In a quick jumping movement, straighten the bent leg out and pull the other knee toward your body. 3. Keep repeating step 2, alternating legs. Notes: Throughout the exercise, your back should remain as straight as possible – avoid a hump or a sagging back.', 'GYM', 'Chest', 'Chest', 'BEGINNER', 5, NULL, NULL, 0, '[]', 'none (bodyweight exercise)', 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Chest', 60, NULL, NULL, 'strength', NULL
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE lower(name) = lower('Mountain climbers') AND exercise_type = 'GYM');

