SELECT gen_random_uuid(), '4-count burpees', '4-count burpees is an exercise targeting Chest.', 'Starting position: Stand straight, feet hip-width apart. Steps: 1. Squat low and support yourself on the floor with your hands between the knees and in front of your feet, your back straight. 2. Keeping your hands on the floor, jump your legs backward into high plank position. 3. Jump your feet forward to return to the squat position. 4. Repeat.', 'GYM', 'Chest', 'Chest', 'BEGINNER', 5, NULL, NULL, 0, '[]', 'none (bodyweight exercise)', 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Chest', 60, NULL, NULL, 'strength', NULL
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE lower(name) = lower('4-count burpees') AND exercise_type = 'GYM');

