SELECT gen_random_uuid(), 'No push-up burpees', 'No push-up burpees is an exercise targeting Chest.', 'Starting position: Stand straight, feet hip-width apart. Steps: 1. Squat low and support yourself on the floor with your hands between the knees and in front of your feet, your back straight. 2. Keeping your hands on the floor, jump your legs backward into high plank position. 3. Jump your feet forward to return to the squat position. 4. Jump up. 5. Repeat.', 'GYM', 'Chest', 'Chest', 'BEGINNER', 5, NULL, NULL, 0, '[]', 'none (bodyweight exercise)', 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Chest', 60, NULL, NULL, 'strength', NULL
