SELECT gen_random_uuid(), 'Floor dips', 'Floor dips is an exercise targeting Arms.', 'Starting position: Sit with your arms behind you, supporting your back.Your fingers should point forward.Your knees should be bent, feet together. Steps: 1. Raise your hips off the ground, straightening your arms. 2. Bend your elbows, bringing your hips down. 3. Straighten your arms, returning to the previous position. 4. Repeat steps 2 and 3. Notes: The exercise''s difficulty depends on how high you bring your hips.', 'GYM', 'Arms', 'Arms', 'BEGINNER', 5, NULL, 'https://wger.de/media/exercise-images/1000/553266a8-a972-48c5-a014-b12afac66f65.png', 0, '[]', 'none (bodyweight exercise)', 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Arms', 60, NULL, NULL, 'strength', NULL
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE lower(name) = lower('Floor dips') AND exercise_type = 'GYM');

