SELECT gen_random_uuid(), 'Child''s pose', 'Child''s pose is an exercise targeting Back.', 'Starting position: Start on all fours, knees, toes, and hands touching the ground. Your two big toes should be touching. Steps: 1. Move your knees so that they''re about hip-width apart. 2. On an exhale, move your pelvis back to sit on your heels. Your hands should still be touching the ground. 3. Relax your upper body, lowering your forehead to the floor and letting your hands move forward naturally. 4. Stay in this pose. Tips: * To leave the pose, walk your arms back under your shoulders and move your upper body up into a seated position.', 'GYM', 'Back', 'Back', 'BEGINNER', 5, NULL, 'https://wger.de/media/exercise-images/1002/ddf91765-8045-4087-bece-de17f33332ce.png', 0, '[]', 'none (bodyweight exercise)', 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Back', 60, NULL, NULL, 'strength', NULL
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE lower(name) = lower('Child''s pose') AND exercise_type = 'GYM');

INSERT INTO exercises (id, name, description, instructions, exercise_type, category, muscle_group, difficulty_level, met_value, video_url, image_avt_url, favorites_count, secondary_muscle_groups, equipment, form_tips, is_active, default_sets, default_reps, default_weight_kg, target_muscle_group, rest_time_seconds, default_duration_minutes, default_intensity_level, movement_type, estimated_calories_per_minute)
SELECT gen_random_uuid(), 'Kettlebell deadlifts', 'Kettlebell deadlifts is an exercise targeting Back.', 'Starting position: Stand hip-width apart, with your kettlebell centered between your ankles. Your back should be straight, your head facing forward. Steps: 1. Hinge at the hips and slightly bend at the knees to put your hands on the kettlebell handles. Your back should be straight as you perform the movement. 2. Grab the kettlebell handles, with your hands pushing in opposite directions as if to pull the handle apart. 3. While contacting your abs and glutes, stand straight up. 4. Hinge at the hips again to bring the kettlebell back down, similarly to step 1. 5. Repeat from step 3. Tips: * Be sure you''re performing the movements correctly, as doing otherwise can lead to injury. For example, do not squat instead of hinging at the hips, do not round your back while reaching for the kettlebell, and do not lean back while standing up.', 'GYM', 'Back', 'Back', 'BEGINNER', 5, NULL, 'https://wger.de/media/exercise-images/1003/772d6e47-3865-4944-9255-7435d0b06782.png', 0, '[]', 'Kettlebell', 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Back', 60, NULL, NULL, 'strength', NULL
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE lower(name) = lower('Kettlebell deadlifts') AND exercise_type = 'GYM');

