SELECT gen_random_uuid(), 'Body-Ups', 'Body-Ups is an exercise targeting Arms.', '1. Assume a plank position on the ground. You should be supporting your bodyweight on your toes and forearms, keeping your torso straight. Your forearms should be shoulder-width apart. This will be your starting position. 2. Pressing your palms firmly into the ground, extend through the elbows to raise your body from the ground. Keep your torso rigid as you perform the movement. 3. Slowly lower your forearms back to the ground by allowing the elbows to flex. 4. Repeat as needed.', 'GYM', 'Arms', 'Arms', 'BEGINNER', 5, NULL, NULL, 0, '[]', 'none (bodyweight exercise)', 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Arms', 60, NULL, NULL, 'strength', NULL
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE lower(name) = lower('Body-Ups') AND exercise_type = 'GYM');

