SELECT gen_random_uuid(), 'Chin tuck', 'Chin tuck is an exercise targeting Back.', 'Starting position: Sit or stand with your back straight. Steps: 1. Use fingers on your chin to slowly tuck your chin in, moving your head back to align it with your spine. 2. Hold for 5 seconds. 3. Go back to normal head position and repeat.', 'GYM', 'Back', 'Back', 'BEGINNER', 5, NULL, NULL, 0, '[]', 'none (bodyweight exercise)', 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Back', 60, NULL, NULL, 'strength', NULL
