SELECT gen_random_uuid(), 'Head turns', 'Head turns is an exercise targeting Shoulders.', 'Starting position: Sit or stand with your back straight and shoulders down. Steps: 1. Sit or stand up straight, shoulders dropped. 2. Turn your head to the side as far as possible. Stop when you hit a barrier and hold for 5 seconds. 3. Return to center position and repeat, changing sides.', 'GYM', 'Shoulders', 'Shoulders', 'BEGINNER', 5, NULL, 'https://wger.de/media/exercise-images/1007/757846d3-78e4-4068-bbca-62e567372c94.png', 0, '[]', 'none (bodyweight exercise)', 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Shoulders', 60, NULL, NULL, 'strength', NULL
