SELECT gen_random_uuid(), 'Back neck stretch', 'Back neck stretch is an exercise targeting Back.', 'Starting position: Sit upright on a chair or a firm pillow. Steps: 1. Breathe out and tilt your head forward, chin to chest, putting hands behind your head. 2. Use your hands to pull your head down lightly and press against your hands with your head to balance out the force. 3. Hold for a bit. 4. Relax your arms and head, opening up a bit with your shoulders. 5. Keep repeating this from step 2 onward.', 'GYM', 'Back', 'Back', 'BEGINNER', 5, NULL, NULL, 0, '[]', 'none (bodyweight exercise)', 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Back', 60, NULL, NULL, 'strength', NULL
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE lower(name) = lower('Back neck stretch') AND exercise_type = 'GYM');

