SELECT gen_random_uuid(), 'Blaze', 'Blaze is an exercise targeting Shoulders.', 'BLAZE is a full-body HIIT workout. Designed to supercharge your cardio fitness and strength. Delivered in its own purpose-built studio, BLAZE is a unique mix of martial arts, intense cardio and strength training.', 'CARDIO', 'Cardio', 'Shoulders', 'BEGINNER', 7, NULL, NULL, 0, '["Biceps", "Hamstrings", "Lats", "Abs"]', 'Mixed equipment', 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, NULL, NULL, NULL, NULL, NULL, 30, 'MEDIUM', 'cardio', 8
