INSERT INTO exercises (id, name, description, instructions, exercise_type, category, muscle_group, difficulty_level, met_value, video_url, image_avt_url, favorites_count, secondary_muscle_groups, equipment, form_tips, is_active, default_sets, default_reps, default_weight_kg, target_muscle_group, rest_time_seconds, default_duration_minutes, default_intensity_level, movement_type, estimated_calories_per_minute)
SELECT gen_random_uuid(), 'Single-arm cable pushdown', 'Single-arm cable pushdown is an exercise targeting Arms.', 'Single-arm cable pushdown is a unilateral isolation exercise that targets the triceps brachii. By working one arm at a time, it helps correct strength imbalances between sides while also engaging the core for stability. Starting position: Stand facing the cable machine with your feet shoulder-width apart. Attach a single handle to the high pulley. Grab the handle with one hand using an overhand grip (pronated), with your elbow bent at approximately 90° and tucked close to your body. Keep your core braced and your back straight. Execution: Push the handle downward in a controlled motion by extending your elbow until your arm is fully extended. Hold the contraction for 1 second at the bottom, then slowly return to the starting position.', 'GYM', 'Arms', 'Arms', 'BEGINNER', 5, NULL, NULL, 0, '["Abs"]', NULL, 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Arms', 60, NULL, NULL, 'strength', NULL
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE lower(name) = lower('Single-arm cable pushdown') AND exercise_type = 'GYM');

INSERT INTO exercises (id, name, description, instructions, exercise_type, category, muscle_group, difficulty_level, met_value, video_url, image_avt_url, favorites_count, secondary_muscle_groups, equipment, form_tips, is_active, default_sets, default_reps, default_weight_kg, target_muscle_group, rest_time_seconds, default_duration_minutes, default_intensity_level, movement_type, estimated_calories_per_minute)
SELECT gen_random_uuid(), 'Alternating bicep curls', 'Alternating bicep curls is an exercise targeting Arms.', 'Starting position: Start standing up with dumbbells in each hand, your back straight and feet hip-width apart. Your arms should be relaxed, pointing down. Your knees should be slightly bent, your abs contracted, and your shoulders down. Steps: 1. Bend one arm at the elbow, bringing the dumbbell up to your shoulder. Your upper arm should remain motionless during this movement. 2. Bring the dumbbell back down until your arm is in its original relaxed position. 3. Repeat, switching arms.', 'GYM', 'Arms', 'Arms', 'BEGINNER', 5, NULL, 'https://wger.de/media/exercise-images/1012/8270fdb8-28f1-4eff-b410-af8642085b3f.png', 0, '[]', 'Dumbbell', 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Arms', 60, NULL, NULL, 'strength', NULL
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE lower(name) = lower('Alternating bicep curls') AND exercise_type = 'GYM');

INSERT INTO exercises (id, name, description, instructions, exercise_type, category, muscle_group, difficulty_level, met_value, video_url, image_avt_url, favorites_count, secondary_muscle_groups, equipment, form_tips, is_active, default_sets, default_reps, default_weight_kg, target_muscle_group, rest_time_seconds, default_duration_minutes, default_intensity_level, movement_type, estimated_calories_per_minute)
SELECT gen_random_uuid(), 'Head tilts', 'Head tilts is an exercise targeting Back.', 'Starting position: Sit or stand with your back straight. Steps: 1. Tilt your head to one side and hold for a bit.2.Return your head to neutral position and hold for a bit. 2. Tilt your head to the other side and hold for a bit. 3. Return your head to neutral position yet again and hold for a bit. 4. Repeat.', 'GYM', 'Back', 'Back', 'BEGINNER', 5, NULL, 'https://wger.de/media/exercise-images/1018/5bbd3879-b6fc-4aaa-9e8e-33ae9a688112.png', 0, '[]', 'none (bodyweight exercise)', 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Back', 60, NULL, NULL, 'strength', NULL
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE lower(name) = lower('Head tilts') AND exercise_type = 'GYM');

