SELECT gen_random_uuid(), 'Chin-ups', 'Chin-ups is an exercise targeting Back.', 'The chin-up (also known as a chin or chinup) is a strength training exercise. People frequently do this exercise with the intention of strengthening muscles such as the latissimus dorsi and biceps, which extend the shoulder and flex the elbow, respectively. In this maneuver, the palms are faced towards the body. It is a form of pull-up in which the range of motion is established in relation to a person''s chin.', 'GYM', 'Back', 'Back', 'BEGINNER', 5, NULL, 'https://wger.de/media/exercise-images/181/Chin-ups-2.png', 0, '[]', 'Pull-up bar', 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Back', 60, NULL, NULL, 'strength', NULL
