SELECT gen_random_uuid(), 'Cycling', 'Cycling is an exercise targeting Cardio.', 'Cycling, also called bicycling or biking, is the use of bicycles for transport, recreation, exercise or sport. People engaged in cycling are referred to as cyclists, bicyclists, or bikers. Apart from two-wheeled bicycles, cycling also includes the riding of unicycles, tricycles, quadracycles, recumbent and similar human-powered vehicles.', 'CARDIO', 'Cardio', 'Cardio', 'BEGINNER', 7, NULL, NULL, 0, '["Hamstrings", "Brachialis", "Glutes", "Lats", "Quads"]', 'none (bodyweight exercise)', 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, NULL, NULL, NULL, NULL, NULL, 30, 'MEDIUM', 'cardio', 8
