SELECT gen_random_uuid(), 'Cable Woodchoppers', 'Cable Woodchoppers is an exercise targeting Abs.', 'Set cable pulley slightly lower than chest height. Keep body facing forward with hips stable. Grab the pulley handle, fully extend your arms and bring your arms forward and across your body. Hold for 1 second at the end of the movement and slowly return to starting position.', 'GYM', 'Abs', 'Abs', 'BEGINNER', 5, NULL, NULL, 0, '[]', NULL, 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Abs', 60, NULL, NULL, 'strength', NULL
