SELECT gen_random_uuid(), 'Facepull', 'Facepull is an exercise targeting Shoulders.', 'Attach a rope to a pulley station set at about chest level. Step back so you''re supporting the weight with arms completely outstretched and assume a staggered (one foot forward) stance. Bend the knees slightly for a stable base. Retract the scapulae (squeeze your partner''s finger with your shoulder blades) and pull the center of the rope slightly up towards the face. A good cue is to think about pulling the ends of the rope apart, not just pulling back. As you near your face, externally rotate so your knuckles are facing the ceiling. Hold for one second at the top position and slowly lower.', 'GYM', 'Shoulders', 'Shoulders', 'BEGINNER', 5, 'https://wger.de/media/exercise-video/222/245a824b-cd39-45f2-b251-2c0b7efead0d.MOV', NULL, 0, '[]', NULL, 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Shoulders', 60, NULL, NULL, 'strength', NULL
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE lower(name) = lower('Facepull') AND exercise_type = 'GYM');

