SELECT gen_random_uuid(), 'High Knee Jumps', 'High Knee Jumps is an exercise targeting Legs.', '- Start with legs slightly wider than shoulder width - Drop into a bodyweight squat - As you hit the bottom of the squat, explode upwards into a jump while simultaneously tucking your knees into your chest midflight. Remain tucked until the apex of your jump. - Land on both feet, making sure your knees are not locked so as to avoid excessive strain upon your joints. Collect yourself into the next rep as quickly but under control as possible.', 'CARDIO', 'Cardio', 'Legs', 'BEGINNER', 7, NULL, 'https://wger.de/media/exercise-images/285/4141e8b2-d9f2-4597-8ef0-7768127fd0ec.png', 0, '["Obliquus externus abdominis", "Abs", "Serratus anterior"]', NULL, 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, NULL, NULL, NULL, NULL, NULL, 30, 'MEDIUM', 'cardio', 8
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE lower(name) = lower('High Knee Jumps') AND exercise_type = 'CARDIO');

