SELECT gen_random_uuid(), 'Barbell Clean and press', 'Barbell Clean and press is an exercise targeting Shoulders.', 'This exercise involves lifting a barbell from the ground to the shoulders, then pressing it overhead. It is a compound movement that targets multiple muscle groups, including the legs, back, shoulders, and arms. It is often used in strength and conditioning programs to improve overall power and athleticism.', 'GYM', 'Shoulders', 'Shoulders', 'BEGINNER', 5, NULL, 'https://wger.de/media/exercise-images/1638/046c09b0-c35d-48d0-a552-39dd49f956d2.webp', 0, '[]', 'Dumbbell', 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Shoulders', 60, NULL, NULL, 'strength', NULL
