SELECT gen_random_uuid(), 'Incline Dumbbell Row', 'Incline Dumbbell Row is an exercise targeting Back.', '1. Using a neutral grip, lean into an incline bench. 2. Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position. 3. Retract the shoulder blades and flex the elbows to row the dumbbells to your side. 4. Pause at the top of the motion, and then return to the starting position.', 'GYM', 'Back', 'Back', 'BEGINNER', 5, NULL, NULL, 0, '["Lats"]', 'Dumbbell, Incline bench', 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Back', 60, NULL, NULL, 'strength', NULL
