SELECT gen_random_uuid(), 'Isometric Wipers', 'Isometric Wipers is an exercise targeting Chest.', 'Assume push-up position, with hands slightly wider than shoulder width. Shift body weight as far as possible to one side, allowing the elbow on that side to flex. Reverse the motion, moving completely over to the other side. Return to the starting position, and repeat for the desired number of repetitions.', 'GYM', 'Chest', 'Chest', 'BEGINNER', 5, NULL, NULL, 0, '["Abs"]', 'none (bodyweight exercise)', 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Chest', 60, NULL, NULL, 'strength', NULL
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE lower(name) = lower('Isometric Wipers') AND exercise_type = 'GYM');

