SELECT gen_random_uuid(), 'Jumping Jacks', 'Jumping Jacks is an exercise targeting Legs.', 'A jumping jack or star jump, also called side-straddle hop in the US military, is a physical jumping exercise performed by jumping to a position with the legs spread wide and the hands going overhead, sometimes in a clap, and then returning to a position with the feet together and the arms at the sides', 'GYM', 'Legs', 'Legs', 'BEGINNER', 5, NULL, 'https://wger.de/media/exercise-images/320/6c9124b6-3551-47a8-9c22-20141c8b9c53.png', 0, '[]', NULL, 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Legs', 60, NULL, NULL, 'strength', NULL
