SELECT gen_random_uuid(), 'Cable Cross-over', 'Cable Cross-over is an exercise targeting Chest.', 'Begin with cables at about shoulder height, one in each hand. Take a step forward so that one foot is in front of the other, for stability, and so that there is tension on the cables. Bring hands together in front of you. Try to make your hands overlap (so that the cables cross) a few inches.', 'GYM', 'Chest', 'Chest', 'BEGINNER', 5, NULL, 'https://wger.de/media/exercise-images/71/Cable-crossover-2.png', 0, '["Shoulders"]', NULL, 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Chest', 60, NULL, NULL, 'strength', NULL
