SELECT gen_random_uuid(), 'Long-Pulley, Narrow', 'Long-Pulley, Narrow is an exercise targeting Back.', 'The exercise is the same as the regular long pulley, but with a narrow grip: Sit down, put your feet on the supporting points and grab the bar with a wide grip. Pull the weight with a rapid movement towards your belly button, not upper. Keep your arms and elbows during the movement close to your body. Your shoulders are pulled together. Let the weight slowly down till your arms are completely stretched.', 'GYM', 'Back', 'Back', 'BEGINNER', 5, NULL, NULL, 0, '["Biceps", "Brachialis"]', NULL, 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Back', 60, NULL, NULL, 'strength', NULL
