SELECT gen_random_uuid(), 'Lying Rotator Cuff Exercise', 'Lying Rotator Cuff Exercise is an exercise targeting Shoulders.', 'This is an excercise for problems with the levator muscles. Primary Infraspinatus, secondary Teres Minor. Lying on side. Keep elbow on waist and in 90 dgr angle. Rotate towards stomach. Add weight as fit.', 'GYM', 'Shoulders', 'Shoulders', 'BEGINNER', 5, NULL, NULL, 0, '[]', 'Dumbbell', 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Shoulders', 60, NULL, NULL, 'strength', NULL
