INSERT INTO exercises (id, name, description, instructions, exercise_type, category, muscle_group, difficulty_level, met_value, video_url, image_avt_url, favorites_count, secondary_muscle_groups, equipment, form_tips, is_active, default_sets, default_reps, default_weight_kg, target_muscle_group, rest_time_seconds, default_duration_minutes, default_intensity_level, movement_type, estimated_calories_per_minute)
SELECT gen_random_uuid(), 'Muscle up', 'Muscle up is an exercise targeting Arms.', 'The body is then explosively pulled up by the arms in a radial pull-up, with greater speed than a regular pull-up. When the bar approaches the upper chest, the wrists are swiftly flexed to bring the forearms above the bar. The body is leaned forward, and the elbows are straightened by activating the triceps. The routine is considered complete when the bar is at the level of the waist and the arms are fully straight. To dismount, the arms are bent at the elbow, and the body is lowered to the floor, and the exercise can be repeated. As a relatively advanced exercise, muscle-ups are typically first learned with an assistive kip. The legs swing (kip) up and provide momentum to assist in the explosive upward force needed to ascend above the bar. More advanced athletes can perform a strict variation of the muscle-up which is done slowly, without any kip. This variation begins with a still dead hang and uses isometric muscle contraction to ascend above the bar in a slow, controlled fashion.', 'GYM', 'Back', 'Arms', 'BEGINNER', 5, NULL, NULL, 0, '[]', 'Pull-up bar', 'Keep the movement controlled, avoid momentum, and stop if pain occurs.', true, 3, 10, NULL, 'Arms', 60, NULL, NULL, 'strength', NULL
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE lower(name) = lower('Muscle up') AND exercise_type = 'GYM');

